  ctx.effect(() => ctx.webServer.register({
    kind: 'exact',
    path: '/__archived-conversations/preview',
    handler: (req: IncomingMessage, res: ServerResponse): void => {
      if (!isTrustedRequest(ctx, req)) {
        sendJson(res, { ok: false, error: ERR_BAD_REQUEST }, 403)
