      const sessionId = sessionIdFrom(req.url)
      if (sessionId === null) {
        sendJson(res, { ok: false, error: ERR_BAD_REQUEST }, 400)
        return
      }
      // IDOR guard: only archived conversations are readable through this route.
      if (!isArchived(ctx, sessionId)) {
